// Los 64 bits que JavaScript guarda para un número (formato binary64 del estándar IEEE 754)
function bits64(x) {
  const dv = new DataView(new ArrayBuffer(8));
  dv.setFloat64(0, x);
  return dv.getBigUint64(0).toString(2).padStart(64, "0");
}
const b = bits64(0.1);
console.log("signo:", b.slice(0, 1));
console.log("exponente:", b.slice(1, 12));
console.log("mantisa:", b.slice(12));
console.log("valor real de 0.1:", (0.1).toFixed(25));
console.log("0.3 termina en:", bits64(0.3).slice(-4), "| 0.1 + 0.2 termina en:", bits64(0.1 + 0.2).slice(-4));
